p=sys.argv[1]; text=open(p,encoding="utf-8").read(); rows={}
for line in text.splitlines():
 m=re.search(r"(?:^|\s)step:(\d+) - (.*)",line)
 if not m: continue
 n=int(m.group(1)); vals={k:float(v) for k,v in re.findall(r"([\w/@]+):(-?[0-9]+(?:\.[0-9]*)?(?:e[+-]?\d+)?)(?: - |$)",m.group(2))}; rows[n]=vals
print("step score response_mean clip entropy grad pg_loss logppl_diff min_logppl_diff")
for n in range(1,401):
 v=rows[n]
 if n<=10 or n%10==0:
  print(n,*[f"{v.get(k,float(chr(110)+chr(97)+chr(110))):.6g}" for k in ["critic/score/mean","response_length/mean","response_length/clip_ratio","actor/entropy","actor/grad_norm","actor/pg_loss","rollout_corr/log_ppl_diff","rollout_corr/log_ppl_diff_min"]])
print("\nfirst zero/nonzero thresholds:")
for k in ["critic/score/mean","actor/grad_norm","actor/pg_loss","response_length/clip_ratio"]:
 z=[n for n,v in rows.items() if v.get(k)==0]; nz=[n for n,v in rows.items() if v.get(k)!=0]
 print(k,"first zero",min(z) if z else None,"zero steps",len(z),"first zero after step100",next((n for n in z if n>=100),None),"first nonzero",min(nz) if nz else None)
print("\nlongest all-zero reward stretches:")
best=(0,None,None); start=None
for n in range(1,402):
 if n<=400 and rows[n]["critic/score/mean"]==0:
  if start is None: start=n
 elif start is not None:
  length=n-start
  if length>best[0]: best=(length,start,n-1)
  start=None
print(best)
