python3 -I -c 'import re,sys,collections
p=sys.argv[1]; rows={}
for line in open(p,encoding="utf-8"):
 m=re.search(r"(?:^|\s)step:(\d+) - (.*)",line)
 if not m: continue
 n=int(m.group(1)); rows[n]={k:float(v) for k,v in re.findall(r"([\w/@]+):(-?[0-9]+(?:\.[0-9]*)?(?:e[+-]?\d+)?)(?: - |$)",m.group(2))}
for k in ["critic/score/mean","actor/grad_norm","actor/pg_loss","response_length/clip_ratio"]:
 z=[n for n in range(1,401) if k in rows[n] and rows[n][k]==0]; nz=[n for n in range(1,401) if k in rows[n] and rows[n][k]!=0]
 print(k,"first zero",min(z),"zero steps",len(z),"first nonzero",min(nz))
 print("nonzero rewards after step150:",[(n,rows[n][k]) for n in range(151,401) if rows[n].get(k,0)!=0] if k=="critic/score/mean" else "")
print("step numbers",min(rows),max(rows),len(rows))
print("eval records:")
for n in sorted(rows):
 if n==0 or "val-core/taco/acc/mean@1" in rows[n]: print(n, rows[n].get("val-core/taco/acc/mean@1"), rows[n].get("val-aux/taco/pass_rate/mean@1"))
