python3 -I -c 'from wandb.sdk.internal.datastore import DataStore
import sys,json
store=DataStore(); store.open_for_scan(sys.argv[1]); count=0
while True:
 try: data=store.scan_data()
 except Exception as e: print("scan end",repr(e)); break
 if data is None: break
 count+=1
 try:
  from wandb.proto import wandb_internal_pb2 as pb
  rec=pb.Record(); rec.ParseFromString(data)
  if rec.HasField("history"):
   print(json.dumps({i.key:(json.loads(i.value_json) if i.value_json else i.nested_key) for i in rec.history.item},sort_keys=True))
  elif rec.HasField("summary"):
   print("SUMMARY",[(i.key,i.value_json) for i in rec.summary.update])
 except Exception as e: print("decode error",repr(e))
print("records",count)' /workspace/logs/wandb/latest-run/run-xr5gf82b.wandb

