for name,p in specs:
 t=pq.read_table(p,columns=['prompt','reward_model','extra_info']); rows=t.to_pylist(); datasets[name]=rows; print(name,'row_count',len(rows),'mean_n_tests',sum(r['extra_info']['n_tests'] for r in rows)/len(rows)); print(name,'rows_gt_100_tests',sum(r['extra_info']['n_tests']>100 for r in rows),'rows_gt_250',sum(r['extra_info']['n_tests']>250 for r in rows)); print(name,'by_code_type', {k:len(v) for k,v in ((k,[r for r in rows if r['extra_info']['code_type']==k]) for k in ['stdin','call_based'])});
