arguments.command:
python3 -I -B -c "import pyarrow.parquet as pq,collections; specs=[('train','/workspace/taco_verl/train.parquet'),('test','/workspace/taco_verl/test.parquet')]; datasets={}
for name,p in specs:
 rows=pq.read_table(p,columns=['prompt','reward_model','extra_info']).to_pylist(); datasets[name]=rows; print(name,'row_count',len(rows),'mean_n_tests',sum(r['extra_info']['n_tests'] for r in rows)/len(rows),'median_n_tests',sorted(r['extra_info']['n_tests'] for r in rows)[len(rows)//2]); print(name,'rows_gt_100_tests',sum(r['extra_info']['n_tests']>100 for r in rows),'rows_gt_250',sum(r['extra_info']['n_tests']>250 for r in rows));
 for col,get in [('prompt',lambda r:str(r['prompt'])),('gt',lambda r:r['reward_model']['ground_truth']),('pid',lambda r:r['extra_info']['problem_id'])]:
  d=collections.defaultdict(list)
  for i,r in enumerate(rows):d[get(r)].append((i,r['extra_info']['problem_id'],r['extra_info']['n_tests']))
  dup=[(v,get(k)[:140]) for k,v in d.items() if len(v)>1]; print(name,'duplicate_'+col,'groups',len(dup),'rows',sum(len(v) for v,_ in dup),'examples',dup[:15])
a=collections.defaultdict(list); b=collections.defaultdict(list)
for i,r in enumerate(datasets['train']):a[str(r['prompt'])].append(i)
for i,r in enumerate(datasets['test']):b[str(r['prompt'])].append(i)
shared=set(a)&set(b); print('cross_prompt_overlap','keys',len(shared),'train_rows',sum(len(a[k]) for k in shared),'test_rows',sum(len(b[k]) for k in shared))"

